def translate(text: str, lang: str) -> str:
    """The sentence in this language, or the English when no translation matches."""
    if lang not in LANGS or not text:
        return text
    i = LANGS.index(lang)
    if text in _WHOLE:
        return _WHOLE[text][i]
    for head in _HEADS:
        if text.startswith(head[0]):
            name = _NAME.get(text[len(head[0]):])
            return head[i + 1] + name[lang] if name else text
    sms = _SMS.match(text)
    if sms:
        for when, row in _WHEN_COMPILED:
            m = when.match(sms["when"])
            if m:
                return _SMS_TEXT[lang][1 if sms["points"] else 0].format(when=row[lang].format(**m.groupdict()))
        return text
    for pattern, row in _COMPILED:
        m = pattern.match(text)
        if m:
            return row[lang].format(**m.groupdict())
    return text


def localise(result: dict) -> dict:
    """Adds the four languages next to the English in a scoring result, in place."""
    for lang in LANGS:
        if result.get("headline_en"):
            result[f"headline_{lang}"] = translate(result["headline_en"], lang)
        for item in (*result.get("reasons", ()), *result.get("advice", ())):
            item[f"text_{lang}"] = translate(item["text_en"], lang)
    return result
